def transform_complete(grid):
    h, w = len(grid), len(grid[0])
    output = [[0]*w for _ in range(h)]

    mid_row = (h - 1) / 2
    print(f"h={h}, mid_row={mid_row}")

    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] == 4:
                is_upper = r0 < mid_row
                print(f"Found 4 at ({r0}, {c0}), is_upper={is_upper}")

                if is_upper:
                    # Upper-half pattern
                    row_ge_col = r0 >= c0

                    if row_ge_col:
                        # Main diagonal pattern
                        for r_fill in range(r0 + 1):
                            if r_fill < h:
                                output[r_fill][r_fill] = 4
                    else:
                        # row < col: horizontal + vertical pattern
                        for c_fill in range(w):
                            dist = abs(c_fill - c0)
                            if dist % 2 == 1:
                                output[r0][c_fill] = 4
                        for r_fill in range(h):
                            if r_fill != r0:
                                dist = abs(r_fill - r0)
                                if dist % 2 == 1:
                                    output[r_fill][c0] = 4
                else:
                    # Lower-half pattern (like Demo 1)
                    # Rule: same row at c0-1, c0+1; down at r0+1, c0; knight moves up at (r0-1, c0-2), (r0-1, c0+2)

                    # Same row: left, right
                    if c0 - 1 >= 0:
                        output[r0][c0 - 1] = 4
                    if c0 + 1 < w:
                        output[r0][c0 + 1] = 4

                    # Down
                    if r0 + 1 < h:
                        output[r0 + 1][c0] = 4

                    # Knight moves UP
                    if r0 - 1 >= 0:
                        if c0 - 2 >= 0:
                            output[r0 - 1][c0 - 2] = 4
                        if c0 + 2 < w:
                            output[r0 - 1][c0 + 2] = 4

    return output

